INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (15,15,'["Quels logiciels de dessin technique maîtrisez-vous (AutoCAD, Revit, ArchiCAD…) et à quel niveau d''utilisation concrète ?", "Comment établissez-vous un plan d''exécution à partir d''un avant-projet sommaire, et quelles vérifications effectuez-vous avant validation ?", "Quelle est la différence entre un plan de coffrage et un plan d''armature, et avez-vous déjà produit ce type de documents ?", "Décrivez précisément votre expérience d''un an : quel type de projets, quelles tâches quotidiennes et quel était votre niveau de responsabilité ?", "Avez-vous déjà travaillé en coordination avec des équipes chantier ou des bureaux d''études, et comment gériez-vous les écarts entre les plans et la réalité terrain ?", "Votre formation à l''ISTA de Fès couvre principalement le dessin de bâtiment : quelles compétences avez-vous développées par vous-même au-delà du programme officiel ?", "Le score de correspondance entre votre profil et le poste CGM est faible — qu''est-ce qui vous a tout de même poussé à candidater et comment comptez-vous combler les écarts identifiés ?", "Où vous voyez-vous professionnellement dans trois ans, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions et des projets portés par l''Agence de Développement Régional Fès-Meknès, et qu''est-ce qui vous a marqué dans son action territoriale ?", "Le secteur public impose des procédures strictes (marchés publics, délais administratifs, reddition de comptes) — comment envisagez-vous de vous adapter à ce cadre après une expérience en secteur privé ?"]','[]','{}','2026-08-27 13:28:31.273254') ON CONFLICT (id) DO NOTHING;